      { que: "F AB", r: "cat({y <- c(44, 34, 30, 49, 48, 43, 62, 56, 58, 68, 70, 58); A <- factor(rep(1:2, each = 6)); B <- factor(rep(rep(1:2, each = 3), 2)); summary(aov(y ~ A * B))[[1]][3, 4]})", esperado: 0.42, tol: 0.0050000010000000004 },
      { que: "CME", r: "cat(format({y <- c(44, 34, 30, 49, 48, 43, 62, 56, 58, 68, 70, 58); A <- factor(rep(1:2, each = 6)); B <- factor(rep(rep(1:2, each = 3), 2)); summary(aov(y ~ A * B))[[1]][4, 3]}, digits = 15))", esperado: 28.25, tol: 0.000500001 },
      { que: "LSD A", r: "cat(qt(0.975, 8) * sqrt(2 * 28.25 / 6))", esperado: 7.076, tol: 0.000500001 },
      { que: "LSD AB", r: "cat(qt(0.975, 8) * sqrt(2 * 28.25 / 3))", esperado: 10.007, tol: 0.000500001 }
